// All values model a fictitious educational network. Animation time is expanded.
import {RoadJourney} from './road-routing.mjs';
export {ROAD} from './road-routing.mjs';
export function along(path,t){let lengths=path.slice(1).map((p,i)=>Math.hypot(p[0]-path[i][0],p[1]-path[i][1]));let d=Math.max(0,Math.min(.999999,t))*lengths.reduce((a,b)=>a+b,0);for(let i=0;i<lengths.length;i++){if(d<=lengths[i]){let f=d/lengths[i];return {x:path[i][0]+(path[i+1][0]-path[i][0])*f,z:path[i][1]+(path[i+1][1]-path[i][1])*f,angle:Math.atan2(path[i+1][0]-path[i][0],path[i+1][1]-path[i][1])}}else d-=lengths[i]}return {x:path.at(-1)[0],z:path.at(-1)[1],angle:0}}
export function crc32(str){let c=0xffffffff;for(const ch of new TextEncoder().encode(str)){c^=ch;for(let j=0;j<8;j++)c=(c>>>1)^((c&1)?0xedb88320:0)}return ((c^0xffffffff)>>>0).toString(16).padStart(8,'0').toUpperCase()}
export function checksum(str){let sum=0;for(const b of new TextEncoder().encode(str)){sum+=b;sum=(sum&65535)+(sum>>>16)}return ((~sum)&65535).toString(16).padStart(4,'0').toUpperCase()}
export class Simulation{
 constructor(){this.listeners=[];this.reset()}
 reset(){this.time=0;this.paused=false;this.speed=1;this.seed=891;this.serial=0;this.load=32;this.traffic=12;this.bandwidth=10;this.protocol='UDP';this.emergency=false;this.progress=0;this.demo=false;this.demoTime=0;this.demoStep=-1;this.complete=false;this.recalcUntil=0;this.routeComparison=null;this.nextStream=1;this.stream=true;this.dropNext=false;this.cwnd=4;this.tcp='CLOSED';this.handshake=[];this.events=[];this.packets=[];this.jobs=[];this.history=[];this.stats={sent:0,delivered:0,lost:0,retries:0,routeChanges:0,bytes:0,delayTotal:0,peak:0};this.received=false;this.confirmed=false;this.p2pUntil=0;this.dns='Not queried';this.frame=null;this.selection='AMB-01';this.source='AMB-01';this.destination='HOSP-01';this.concept=['Packet switching','Phase 1 · Network foundation'];
 let raw=[['AMB-01','Ambulance',-42,30,'192.168.10.21'],['POL-01','Police',-32,0,'192.168.10.22'],['FIRE-01','Fire',20,28,'192.168.10.23'],...Array.from({length:6},(_,i)=>[`RSU-0${i+1}`,'RSU',[-37,-17,23,-17,23,39][i],[25,5,5,-25,-25,25][i],`192.168.20.${10+i}`]),['R1','Router',-30,-13,'192.168.30.1'],['R2','Router',-2,18,'192.168.30.2'],['R4','Router',4,-15,'192.168.30.4'],['R5','Router',34,-13,'192.168.30.5'],['CTRL','Control center',-3,-40,'192.168.100.10'],['HOSP-01','Hospital',36,-34,'192.168.40.20'],['HOSP-02','Hospital',-39,-34,'192.168.40.21']];
 this.nodes=raw.map((n,i)=>({id:n[0],type:n[1],x:n[2],z:n[3],ip:n[4],mac:`02:1A:2B:3C:4D:${(i+1).toString(16).padStart(2,'0').toUpperCase()}`,radius:32,status:'online'}));this.connected='RSU-01';
 this.links=[];let add=(a,b,delay=4)=>this.links.push({id:`${a}~${b}`,a,b,delay,bandwidth:10,packetLoss:.002,congestion:0,status:'online'});
 for(let i=1;i<=6;i++)add(`RSU-0${i}`,i===4?'R1':i===5?'R5':'R2',3);
 add('R2','R4',4);add('R2','R1',8);add('R1','R5',8);add('R5','R4',8);add('R4','CTRL',3);add('R5','CTRL',5);add('R1','HOSP-02',4);add('CTRL','HOSP-01',4);add('CTRL','HOSP-02',8);add('RSU-01','R1',11);add('RSU-03','R5',10);this.road=new RoadJourney(this.nodes);this.updateAccess();this.route=this.routeFor(this.source,this.destination);this.log('NETWORK ONLINE · 16 addressed nodes ready','System','Packet switching');this.emit()}
 rand(){this.seed=(Math.imul(1664525,this.seed)+1013904223)>>>0;return this.seed/4294967296}
 on(fn){this.listeners.push(fn);return()=>this.listeners=this.listeners.filter(f=>f!==fn)}
 emit(){for(const f of this.listeners)f(this)}
 node(id){return this.nodes.find(n=>n.id===id)}
 link(a,b){return this.links.find(l=>(l.a===a&&l.b===b)||(l.a===b&&l.b===a))}
 log(message,category='Packets',concept='Packet switching'){this.events.unshift({id:++this.serial,time:this.time,message,category,concept});this.events=this.events.slice(0,500);this.concept=[concept,({Routing:'Phase 3 · Network layer',TCP:'Phase 4 · Transport',Emergency:'Phase 5 · Application',Errors:'Phase 2 · Error control'})[category]||'Phase 1 · Network foundation']}
 effectiveLoad(){return Math.min(100,this.load+Math.max(0,this.traffic-12)*2)}
 linkAvailable(l){return !!l&&l.status!=='failed'&&this.node(l.a)?.status==='online'&&this.node(l.b)?.status==='online'}
 cost(l,mode='cost'){if(!this.linkAvailable(l))return Infinity;if(mode==='rip')return 1;const c=this.effectiveLoad()/100;return l.delay*(1+c*2)+l.packetLoss*1000+c*6+1}
 distanceVector(source=this.source,dest=this.destination){if(this.node(source)?.status!=='online'||this.node(dest)?.status!=='online')return[];let distance=Object.fromEntries(this.nodes.map(n=>[n.id,Infinity])),previous={};distance[source]=0;for(let i=0;i<this.nodes.length-1;i++){let changed=false;for(const l of this.links.filter(l=>this.linkAvailable(l)))for(const [a,b] of [[l.a,l.b],[l.b,l.a]])if((this.node(a).type!=='Hospital'||a===source)&&distance[a]+1<distance[b]){distance[b]=distance[a]+1;previous[b]=a;changed=true}if(!changed)break}if(distance[dest]>15)return[];let p=[dest];while(p[0]!==source){if(!previous[p[0]])return[];p.unshift(previous[p[0]])}return p}
 routeFor(source=this.source,dest=this.destination,mode='cost',exclude=null){if(this.node(source)?.status!=='online'||this.node(dest)?.status!=='online')return[];let d=new Map(this.nodes.map(n=>[n.id,Infinity])),prev={},q=new Set(d.keys());d.set(source,0);while(q.size){let u=[...q].sort((a,b)=>d.get(a)-d.get(b))[0];q.delete(u);if(!isFinite(d.get(u))||u===dest)break;if(this.node(u).type==='Hospital'&&u!==source)continue;for(const l of this.links){if(l.id===exclude||!this.linkAvailable(l))continue;let v=l.a===u?l.b:l.b===u?l.a:null;if(!v||!q.has(v))continue;let nd=d.get(u)+this.cost(l,mode);if(nd<d.get(v)){d.set(v,nd);prev[v]=u}}}if(!isFinite(d.get(dest)))return[];let p=[dest];while(p[0]!==source){if(!prev[p[0]])return[];p.unshift(prev[p[0]])}return p}
 routeInfo(path){let links=path.slice(1).map((n,i)=>this.link(path[i],n)).filter(Boolean);return{delay:links.reduce((s,l)=>s+l.delay*(1+2*this.effectiveLoad()/100)+512*8/(this.bandwidth*1000),0),cost:links.reduce((s,l)=>s+this.cost(l),0),loss:(1-links.reduce((s,l)=>s*(1-this.lossRate(l)),1))*100,hops:links.length,bandwidth:this.bandwidth,status:!path.length?'UNREACHABLE':links.some(l=>!this.linkAvailable(l))?'FAILED':'AVAILABLE'}}
 // Save both paths with the same positions, load and bandwidth at the node change.
 snapshotRoute(){const path=this.routeFor(),info=this.routeInfo(path);return{path:[...path],source:this.source,destination:this.destination,delay:path.length?info.delay:null,hops:path.length?info.hops:null,load:this.effectiveLoad(),bandwidth:this.bandwidth}}
 compareNodeChange(nodeId,action,before,roadBefore){const roadAfter=this.road.snapshot();this.routeComparison={nodeId,action,time:this.time,readyAt:this.recalcUntil,before,after:this.snapshotRoute(),road:{before:roadBefore,after:roadAfter,changed:JSON.stringify(roadBefore.path)!==JSON.stringify(roadAfter.path)}}}
 lossRate(l){return Math.min(.3,l.packetLoss+Math.pow(this.effectiveLoad()/100,4)*.035)}
 updateAccess(){this.links=this.links.filter(l=>!l.access);for(const id of ['AMB-01','POL-01','FIRE-01']){let n=this.node(id),rsus=this.nodes.filter(r=>r.type==='RSU'&&r.status==='online').map(r=>({r,d:Math.hypot(r.x-n.x,r.z-n.z)})).filter(v=>v.d<=v.r.radius).sort((a,b)=>a.d-b.d);if(rsus.length){let r=rsus[0].r;this.links.push({id:`${id}~${r.id}`,a:id,b:r.id,delay:2,bandwidth:this.bandwidth,packetLoss:.003,congestion:0,status:'online',access:true});if(id==='AMB-01'&&this.connected!==r.id){let old=this.connected;this.connected=r.id;this.log(`Handoff ${old} → ${r.id} · coverage ${Math.round(rsus[0].d)} m`,'Routing','WLAN handoff');this.route=this.routeFor();}}else if(id==='AMB-01')this.connected=null}}
 schedule(after,fn){this.jobs.push({at:this.time+after,fn})}
 createFrame(payload='EMERGENCY|AMB-01|CRITICAL|HOSP-01'){let route=this.routeFor();this.frame={payload,original:payload,source:this.node(this.source).mac,destination:this.node(route[1]||this.destination).mac,type:'0x0800 · IPv4',crc:crc32(payload),checksum:checksum(payload),status:'UNCHECKED'};this.log('Frame generated · hop-local MAC addresses attached','Packets','Framing');return this.frame}
 checkCRC(){if(!this.frame)this.createFrame();this.frame.status=crc32(this.frame.payload)===this.frame.crc?'VALID':'ERROR';this.log(`CRC-32 ${this.frame.status} · ${this.frame.crc}`,this.frame.status==='ERROR'?'Errors':'Packets','Error control');return this.frame.status}
 corrupt(){if(!this.frame)this.createFrame();this.frame.payload+='!';this.frame.status='UNCHECKED';this.log('Frame payload bit error injected','Errors','CRC')}
 retransmitFrame(){this.createFrame();this.checkCRC();this.send('Frame retry');this.log('Link-layer retry · new valid frame transmitted','Packets','Error control')}
 send(kind='Telemetry',opts={}){let source=opts.source||this.source,destination=opts.destination||this.destination,protocol=opts.protocol||this.protocol;let route=opts.route||this.routeFor(source,destination);if(!route.length||route.some(id=>this.node(id)?.status!=='online')){this.log(`No route from ${source} to ${destination}`,'Errors','ICMP destination unreachable');return null}let id=`PKT-${String(++this.serial).padStart(5,'0')}`;let p={id,source,destination,kind,protocol,priority:kind==='Emergency alert'?'CRITICAL':opts.priority||'NORMAL',size:opts.control?64:512,timestamp:this.time,status:'IN FLIGHT',route,hop:0,progress:0,ttl:64,delay:0,attempt:opts.attempt||0,control:!!opts.control,onDeliver:opts.onDeliver,forceLoss:!!opts.forceLoss,crc:crc32(`${kind}|${source}|${destination}`),payload:`${kind}|${source}|${destination}`};this.packets.push(p);this.stats.sent++;if(this.packets.length>350)this.packets=this.packets.filter(p=>!['DELIVERED','LOST'].includes(p.status)).concat(this.packets.filter(p=>['DELIVERED','LOST'].includes(p.status)).slice(-200));this.log(`${id} · ${kind} · ${protocol} transmitted`,'Packets',protocol==='UDP'?'UDP datagram':'Packet switching');return p}
 lose(p){p.status='LOST';this.stats.lost++;this.log(`${p.id} lost · ${p.protocol==='TCP'&&!p.control?'timeout scheduled':'no transport retry'}`,'Errors','Packet loss');if(p.protocol==='TCP'&&!p.control&&p.attempt<3){this.cwnd=Math.max(1,Math.floor(this.cwnd/2));this.schedule(1.2,()=>{this.stats.retries++;this.log(`${p.id} timeout · retransmitting`,'TCP','TCP retransmission');this.send(p.kind,{source:p.source,destination:p.destination,protocol:'TCP',attempt:p.attempt+1,onDeliver:p.onDeliver})})}}
 delivered(p){p.status='DELIVERED';p.deliveredAt=this.time;this.stats.delivered++;this.stats.bytes+=p.size;this.stats.delayTotal+=p.delay;this.stats.peak=Math.max(this.stats.peak,p.delay);this.log(`${p.id} delivered · ${p.delay.toFixed(1)} ms`,'Packets','Packet switching');if(p.kind==='Emergency alert'){this.received=true;this.log('HTTP 200 OK · hospital accepted POST /api/emergency','Emergency','Client-server')}if(p.protocol==='TCP'&&!p.control){this.cwnd=Math.min(24,this.cwnd+1);this.send('ACK',{source:p.destination,destination:p.source,protocol:'TCP',control:true,onDeliver:()=>{this.confirmed=true;this.log('Hospital acknowledgement received','TCP','Acknowledgement')}})}p.onDeliver?.()}
 connectTCP(callback){if(this.tcp==='ESTABLISHED'){callback?.();return}if(this.tcp!=='CLOSED')return;this.tcp='SYN SENT';this.handshake=['SYN →'];this.log('SYN → hospital','TCP','TCP handshake');this.send('SYN',{protocol:'TCP',control:true,onDeliver:()=>{this.tcp='SYN-ACK';this.handshake.push('← SYN-ACK');this.send('SYN-ACK',{source:this.destination,destination:this.source,protocol:'TCP',control:true,onDeliver:()=>{this.handshake.push('ACK →');this.send('ACK',{protocol:'TCP',control:true,onDeliver:()=>{this.tcp='ESTABLISHED';this.log('TCP connection established','TCP','Three-way handshake');callback?.()}})}})}})}
 activate(send=true){this.source='AMB-01';this.destination='HOSP-01';this.emergency=true;this.log('AMB-01 · CRITICAL emergency · traffic priority enabled','Emergency','Application data');this.resolveDNS();this.createFrame();this.checkCRC();if(send)this.send('Emergency alert',{protocol:'UDP'})}
 resolveDNS(){this.dns='Query sent';this.log('DNS query: emergency-center.local','Packets','DNS');this.schedule(.6,()=>{this.dns='192.168.100.10';this.log('DNS response: 192.168.100.10 (simulated)','Packets','DNS')})}
 failLink(id='R2~R4'){let l=this.links.find(l=>l.id===id)||this.links.find(l=>l.a==='R2'&&l.b==='R4');if(!l||l.status==='failed')return;l.status='failed';this.recalcUntil=this.time+2;this.stats.routeChanges++;for(const p of this.packets.filter(p=>p.status==='IN FLIGHT'))if(p.route.slice(p.hop+1).some((n,i)=>this.link(p.route[p.hop+i],n)?.id===l.id))p.status='REROUTING';this.log(`${l.a} ↔ ${l.b} LINK FAILED · recalculating`,'Routing','Dynamic routing');this.schedule(2,()=>{this.route=this.routeFor();this.log(this.route.length?`Alternate route selected · ${this.route.join(' → ')}`:'No alternate route available','Routing','Link-state routing')})}
 failNode(id){const n=this.node(id);if(!n||!['Router','RSU'].includes(n.type)||n.status==='offline')return false;const before=this.snapshotRoute(),roadBefore=this.road.snapshot();n.status='offline';this.road.replan(this.nodes);this.recalcUntil=this.time+2;this.stats.routeChanges++;for(const p of this.packets.filter(p=>['IN FLIGHT','QUEUED','REROUTING'].includes(p.status))){if(p.route[p.hop]===id)this.lose(p);else if(p.route.slice(p.hop+1).includes(id))p.status='REROUTING'}this.updateAccess();this.compareNodeChange(id,'disabled',before,roadBefore);this.log(`${id} NODE OFFLINE · incident connections unavailable · recalculating`,'Routing','Node failure');this.schedule(2,()=>{this.route=this.routeFor();this.log(this.route.length?`Alternate route selected · ${this.route.join(' → ')}`:'No alternate route available · restore a node or connection','Routing','Link-state routing')});return true}
 restoreNode(id){const n=this.node(id);if(!n||n.status!=='offline')return false;const before=this.snapshotRoute(),roadBefore=this.road.snapshot();n.status='online';this.road.replan(this.nodes);this.updateAccess();this.route=this.routeFor();this.recalcUntil=0;this.compareNodeChange(id,'restored',before,roadBefore);this.log(`${id} restored · routes recalculated`,'Routing','Node recovery');return true}
 restore(){this.routeComparison=null;for(const n of this.nodes)n.status='online';for(const l of this.links)l.status='online';this.road.replan(this.nodes);this.updateAccess();this.route=this.routeFor();this.recalcUntil=0;this.log('All nodes and links restored · topology converged','Routing','Link-state routing')}
 injectLoss(){let p=this.packets.find(p=>p.status==='IN FLIGHT'&&!p.control);if(p)this.lose(p);else this.dropNext=true}
 p2p(){this.p2pUntil=this.time+5;this.log('AMB-01 → POL-01: Clear Road B for AMB-01','Emergency','Peer-to-peer');this.send('P2P · clear Road B',{source:'AMB-01',destination:'POL-01',protocol:'UDP',route:['AMB-01','POL-01']})}
 runDemo(){this.reset();this.demo=true;this.stream=false;this.log('60-second guided demonstration started','Emergency','TCP/IP')}
 demoActions(){let t=this.demoTime;let steps=[0,5,10,15,25,30,35,45,50,55];let k=steps.findLastIndex(v=>t>=v);if(k!==this.demoStep){this.demoStep=k;switch(k){case 1:this.activate(false);break;case 2:this.createFrame();this.checkCRC();break;case 3:this.stream=true;this.send('Emergency alert');break;case 4:this.failLink();break;case 5:this.log('Lowest-cost available path recalculated','Routing','Dynamic routing');break;case 6:this.load=78;this.log('Congestion injected · queues growing','Routing','Congestion');break;case 7:this.load=32;this.send('Emergency alert');break;case 8:this.protocol='TCP';this.stream=false;this.connectTCP(()=>this.send('Hospital confirmation',{protocol:'TCP',forceLoss:true}));break;case 9:this.log('Collecting delivery, retry and route analytics','System','Network performance');break}}if(t>=60){this.demo=false;this.complete=true;this.stream=false;this.paused=true;this.log('Full demonstration complete · analytics available','Emergency','Network performance')}}
 tick(dt){if(this.paused)return;dt=Math.min(dt,.1)*this.speed;this.time+=dt;if(this.demo){this.demoTime+=dt;this.demoActions()}if(this.emergency&&this.progress<1&&this.time>=this.recalcUntil){this.road.advance(dt);this.progress=this.road.progress;Object.assign(this.node('AMB-01'),this.road.position);if(this.progress===1){this.log('AMB-01 arrived at HOSP-01 · patient handover','Emergency','Client-server');this.send('Emergency alert',{protocol:'UDP'})}}for(const [id,path] of [['POL-01',[[-32,2],[18,2],[18,28],[-22,28],[-22,2],[-32,2]]],['FIRE-01',[[22,28],[22,-28],[46,-28],[46,28],[22,28]]]]){Object.assign(this.node(id),along(path,(this.time*.002)%1))}this.updateAccess();if(this.time>=this.recalcUntil)this.route=this.routeFor();let ready=this.jobs.filter(j=>j.at<=this.time);this.jobs=this.jobs.filter(j=>j.at>this.time);ready.forEach(j=>j.fn());
 if(this.stream&&this.time>=this.nextStream){this.nextStream=this.time+Math.max(.38,1.5-this.effectiveLoad()/100);if(this.protocol==='UDP')this.send(this.emergency?'GPS':'Telemetry');else if(this.tcp==='ESTABLISHED'){if(this.packets.filter(p=>p.protocol==='TCP'&&!p.control&&['IN FLIGHT','QUEUED','REROUTING'].includes(p.status)).length<this.cwnd)this.send('TCP data')}else this.connectTCP()}
 for(const p of [...this.packets]){if(!['IN FLIGHT','REROUTING','QUEUED'].includes(p.status))continue;if(p.status==='REROUTING'){if(this.time<this.recalcUntil)continue;let next=this.routeFor(p.route[p.hop],p.destination);if(!next.length)continue;p.route=[...p.route.slice(0,p.hop),...next];p.progress=0;p.status='IN FLIGHT'}let a=p.route[p.hop],b=p.route[p.hop+1];if(!b){this.delivered(p);continue}let l=this.link(a,b);if(p.kind.startsWith('P2P'))l={delay:2,status:'online',packetLoss:0};if(!this.linkAvailable(l)&&!p.kind.startsWith('P2P')){p.status='REROUTING';continue}let load=this.effectiveLoad()/100;let duration=p.control?.13:.27+l.delay*.015+load*.25;
 p.status=load>.7&&p.progress<.22&&this.node(a)?.type==='Router'?'QUEUED':'IN FLIGHT';p.progress+=dt/duration;if(p.progress>=1){if((this.dropNext||p.forceLoss||this.rand()<this.lossRate(l))&&!p.control){this.dropNext=false;p.forceLoss=false;this.lose(p);continue}p.progress=0;p.hop++;p.ttl--;p.delay+=l.delay*(1+2*load)+p.size*8/(this.bandwidth*1000);if(p.hop>=p.route.length-1)this.delivered(p);else if(p.ttl<=0){this.lose(p);this.log('ICMP time exceeded','Errors','IPv4 TTL')}}}
 if(!this.history.length||this.time-this.history.at(-1).time>=1){let m=this.metrics();this.history.push({time:this.time,...m,cwnd:this.cwnd,load:this.effectiveLoad()});this.history=this.history.slice(-120)}this.emit()}
 metrics(){let info=this.routeInfo(this.route),recent=this.packets.filter(p=>p.status==='DELIVERED'&&this.time-p.deliveredAt<5);return{delay:info.delay,loss:this.stats.sent?100*this.stats.lost/this.stats.sent:0,throughput:recent.reduce((s,p)=>s+p.size*8,0)/5/1e6,capacity:this.bandwidth*(1-this.effectiveLoad()/100*.6),queue:this.packets.filter(p=>p.status==='QUEUED').length,active:this.packets.filter(p=>['IN FLIGHT','QUEUED','REROUTING'].includes(p.status)).length,average:this.stats.delivered?this.stats.delayTotal/this.stats.delivered:0}}
}
